<!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ziyaretler - AdGuard</title><link rel="stylesheet" href="<?= e(url('/assets/app.css')) ?>"></head>
<body><main class="container"><h1>Ziyaret geçmişi</h1><p><a href="<?= e(url('/dashboard')) ?>">Panel</a> · <a href="<?= e(url('/ip-rules')) ?>">IP yönetimi</a></p>
<form method="get" action="<?= e(url('/visits')) ?>"><label>Web sitesi</label><select name="website_id"><option value="0">Tüm siteler</option><?php foreach($websites as $site): ?><option value="<?= (int)$site['id'] ?>" <?= (int)($_GET['website_id']??0)===(int)$site['id']?'selected':'' ?>><?= e($site['name']) ?></option><?php endforeach; ?></select><label>Risk seviyesi</label><select name="risk_level"><option value="">Tümü</option><?php foreach(['low','medium','high','critical'] as $level): ?><option value="<?= e($level) ?>" <?= ($_GET['risk_level']??'')===$level?'selected':'' ?>><?= e($level) ?></option><?php endforeach; ?></select><button type="submit">Filtrele</button></form>
<table><thead><tr><th>Tarih</th><th>Site</th><th>IP</th><th>Risk</th><th>Puan</th><th></th></tr></thead><tbody><?php foreach($visits as $visit): ?><tr><td><?= e($visit['created_at']) ?></td><td><?= e($visit['website_name']) ?></td><td><?= e(inet_ntop($visit['ip_address'])) ?></td><td><?= e($visit['risk_level']) ?></td><td><?= (int)$visit['risk_score'] ?></td><td><a href="/visit?id=<?= (int)$visit['id'] ?>">Detay</a></td></tr><?php endforeach; ?></tbody></table>
</main></body></html>
